def check_claims(c, iss, client_id, nonce, now):
    errs = []
    if c.get("iss") != iss: errs.append("iss 다름")
    aud = c.get("aud"); aud = aud if isinstance(aud, list) else [aud]
    if client_id not in aud: errs.append("aud 에 내 client_id 없음")
    if now >= c.get("exp", 0): errs.append("만료됨(exp)")
    if c.get("nonce") != nonce: errs.append("nonce 다름(재전송 의심)")
    return errs or ["통과"]

now = 1_800_000_000
good = {"iss": "https://id.example.jp/realms/hosp-a", "sub": "u123", "aud": "medcom-app",
        "exp": now + 300, "iat": now, "nonce": "n-42"}
print(check_claims(good, "https://id.example.jp/realms/hosp-a", "medcom-app", "n-42", now))
bad = dict(good, iss="https://id.example.jp/realms/hosp-b", exp=now - 1)
print(check_claims(bad, "https://id.example.jp/realms/hosp-a", "medcom-app", "n-42", now))
